fn main() {
    let mut num = 5;

    let r1 = &raw const num;
    let r2 = &raw mut num;

    unsafe {
        *r2 += 1;
        println!("r1 is: {}", *r1);
        println!("r2 is: {}", *r2);
    }

    let address = 0x012345usize;
    let _r = address as *const i32; // creating it is fine; dereferencing it would be UB
}

fn main() {
    let mut num = 5;
    let r1 = &raw const num;
    println!("r1 is: {}", *r1);
}

/// Returns the element at `index` without bounds checking.
///
/// # Safety
///
/// `index` must be less than `values.len()`.
unsafe fn get_unchecked(values: &[i32], index: usize) -> i32 {
    // SAFETY: the caller promises index < values.len()
    unsafe { *values.as_ptr().add(index) }
}

fn main() {
    let v = [10, 20, 30];
    // SAFETY: 2 < 3
    let x = unsafe { get_unchecked(&v, 2) };
    println!("{x}");
}

fn split_at_mut(values: &mut [i32], mid: usize) -> (&mut [i32], &mut [i32]) {
    let len = values.len();

    assert!(mid <= len);

    (&mut values[..mid], &mut values[mid..])
}

