use std::slice;

fn split_at_mut(values: &mut [i32], mid: usize) -> (&mut [i32], &mut [i32]) {
    let len = values.len();
    let ptr = values.as_mut_ptr();

    assert!(mid <= len);

    // SAFETY: ptr is valid for len elements; [0, mid) and [mid, len) do not overlap,
    // and both stay within the original slice, which is borrowed mutably for the result's lifetime.
    unsafe {
        (
            slice::from_raw_parts_mut(ptr, mid),
            slice::from_raw_parts_mut(ptr.add(mid), len - mid),
        )
    }
}

fn main() {
    let mut v = vec![1, 2, 3, 4, 5, 6];
    let (a, b) = split_at_mut(&mut v, 3);
    a[0] = 100;
    b[0] = 400;
    println!("{a:?} {b:?}");
}

unsafe extern "C" {
    safe fn abs(input: i32) -> i32;
    fn strlen(s: *const std::ffi::c_char) -> usize;
}

fn main() {
    println!("Absolute value of -3 according to C: {}", abs(-3));

    let text = c"hello";
    // SAFETY: text is a valid, NUL-terminated C string
    let n = unsafe { strlen(text.as_ptr()) };
    println!("strlen says {n}");
}

use std::sync::atomic::{AtomicU32, Ordering};

static mut COUNTER: u32 = 0;
static SAFE_COUNTER: AtomicU32 = AtomicU32::new(0);

/// # Safety
///
/// Calling this from more than one thread at a time is undefined behavior.
unsafe fn add_to_count(inc: u32) {
    // SAFETY: the caller guarantees single-threaded access
    unsafe {
        COUNTER += inc;
    }
}

fn main() {
    unsafe {
        // SAFETY: main is the only thread
        add_to_count(3);
        println!("COUNTER: {}", *(&raw const COUNTER));
    }

    SAFE_COUNTER.fetch_add(3, Ordering::Relaxed);
    println!("SAFE_COUNTER: {}", SAFE_COUNTER.load(Ordering::Relaxed));
}

#[repr(C)]
union IntOrFloat {
    i: u32,
    f: f32,
}

struct RawHandle(*mut u8);

// SAFETY: the pointer is only used by the thread that owns the handle
unsafe impl Send for RawHandle {}

fn main() {
    let u = IntOrFloat { f: 1.0 };
    // SAFETY: every bit pattern is a valid u32
    let bits = unsafe { u.i };
    println!("1.0f32 has bits {bits:#010x}");

    let h = RawHandle(std::ptr::null_mut());
    let t = std::thread::spawn(move || {
        let h = h; // capture the whole handle, not just its field
        h.0.is_null()
    });
    println!("null in thread: {}", t.join().unwrap());
}

